// The owner may coalesce physical reads while preserving the same descriptor
// identity, diagnostics and Close lifetime. This is below all codec validation.
type compressedBlockPhysicalFile interface {
	io.ReaderAt
	io.Closer
	Name() string

// Immutable history files repeatedly read small physical header, directory and
// frame fields. Coalesce only small reads on this open descriptor; large
// payloads still use one direct read. Validation remains in existing callers.

func newHistoryPhysicalPages(ctx context.Context, file *os.File, size uint64, prefix int) *historyAccessorPages {
	return &historyAccessorPages{file: file, pages: acquireHistoryDirectoryPages(ctx, file, 0, size), prefix: prefix}
}

func (r *historyAccessorPages) Name() string { return r.file.Name() }

	return r.readWindow(dst, off)
}

// Anchor a miss at the requested offset. Accessor directory pages start after
// their header, rather than at OS page boundaries; rounding a 4KiB request down
// would issue two reads and overfetch on every unaligned directory miss.
// Keep the tiny accessor prefix bounded separately from segment frame headers.
func (r *historyAccessorPages) readWindow(dst []byte, off int64) (int, error) {
	p := r.pages
	for i := 0; i < p.count; i++ {
		page := &p.pages[i]
		if page.offset >= 0 && off >= page.offset && off-page.offset <= int64(page.size) && int64(len(dst)) <= int64(page.size)-(off-page.offset) {
			return copy(dst, page.bytes[off-page.offset:]), nil
		}
	}
	index := p.next
	if p.count < historyDirectoryPageCount {
		index = p.count
	}
	page := &p.pages[index]
	page.offset = -1
	start, length := off, int64(historyDirectoryPageSize)
	if off < int64(r.prefix) && int64(len(dst)) <= int64(r.prefix)-off {
		start, length = 0, int64(r.prefix)
	}
	size := int(min(length, p.end-start))
	n, err := p.source.ReadAt(page.bytes[:size], start)
	if err != nil {
		return 0, err
	}
	if n != size {
		return 0, io.ErrUnexpectedEOF
	}
	page.offset, page.size = start, size
	if p.count < historyDirectoryPageCount {
		p.count++
	} else {
		p.next = (p.next + 1) % historyDirectoryPageCount
	}
	return copy(dst, page.bytes[off-start:]), nil

type historyPhysicalProbe struct {
	historyPageProbe
	requested int
}

func (p *historyPhysicalProbe) ReadAt(dst []byte, off int64) (int, error) {
	p.requested += len(dst)
	return p.historyPageProbe.ReadAt(dst, off)
}

func TestHistoryAccessorPagesUnalignedReadAmplificationAndFailedReuse(t *testing.T) {
	data := bytes.Repeat([]byte{7}, 14*historyDirectoryPageSize)
	path := filepath.Join(t.TempDir(), "accessor.kv")
	if err := os.WriteFile(path, data, 0600); err != nil {
		t.Fatal(err)
	}
	file, err := os.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	r := newHistoryAccessorPages(context.Background(), file, uint64(len(data)))
	defer r.Close()
	probe := &historyPhysicalProbe{historyPageProbe: historyPageProbe{data: data}}
	r.pages.source = probe
	for _, size := range []int{8, 36, 12, 120} {
		if _, err := r.ReadAt(make([]byte, size), 0); err != nil {
			t.Fatal(err)
		}
	}
	if probe.calls != 1 || probe.requested != 128 {
		t.Fatal("small header read amplification", probe.calls, probe.requested)
	}
	page := make([]byte, 4096)
	if _, err := r.ReadAt(page, 120); err != nil {
		t.Fatal(err)
	}
	if probe.calls != 2 || probe.requested != 128+4096 {
		t.Fatal("unaligned directory split into multiple reads", probe.calls, probe.requested)
	}
	for i := 1; i < historyDirectoryPageCount; i++ {
		if _, err := r.ReadAt(page, int64(120+i*4096)); err != nil {
			t.Fatal(err)
		}
	}
	probe.fail = true
	if _, err := r.ReadAt(page, 120+10*4096); !errors.Is(err, io.ErrUnexpectedEOF) {
		t.Fatal(err)
	}
	probe.fail = false
	data[0] = 9
	before := probe.calls
	if _, err := r.ReadAt(page[:8], 0); err != nil || page[0] != 9 || probe.calls != before+1 {
		t.Fatal("failed window reused stale bytes", err, page[0], probe.calls)
	}
}

func TestHistoryAccessorPagesCompressedSourceLifetimeAndValidation(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "history.seg")
	raw := bytes.Repeat([]byte("history-physical-prefix-"), 9000)
	if err := compressBlobToFile(dir, path, raw, historyCompressChunkSize); err != nil {
		t.Fatal(err)
	}
	open := func() (*compressedBlockReader, *historyAccessorPages, error) {
		file, err := os.Open(path)
		if err != nil {
			return nil, nil, err
		}
		stat, err := file.Stat()
		if err != nil {
			file.Close()
			return nil, nil, err
		}
		pages := newHistoryAccessorPages(context.Background(), file, uint64(stat.Size()))
		var magic [8]byte
		if _, err := pages.ReadAt(magic[:], 0); err != nil {
			pages.Close()
			return nil, pages, err
		}
		reader, err := openCompressedBlockFileWithCacheLimitContext(context.Background(), pages, stat, 1)
		return reader, pages, err
	}
	reader, pages, err := open()
	if err != nil {
		t.Fatal(err)
	}
	buf := make([]byte, 128)
	if _, err := reader.ReadAt(buf, 0); err != nil || !bytes.Equal(buf, raw[:128]) {
		t.Fatal("buffered compressed prefix", err)
	}
	if err := reader.Close(); err != nil || pages.pages != nil {
		t.Fatal("physical pages survived compressed close", err)
	}
	if _, err := pages.file.ReadAt(buf, 0); !errors.Is(err, os.ErrClosed) {
		t.Fatal("physical descriptor leaked", err)
	}
	// A later open must read changed physical bytes rather than pooled pages.
	file, err := os.OpenFile(path, os.O_RDWR, 0)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := file.WriteAt([]byte("BROKEN!!"), 0); err != nil {
		t.Fatal(err)
	}
	file.Close()
	if reader, pages, err = open(); err == nil {
		reader.Close()
		t.Fatal("fresh compressed open accepted stale magic")
	}
	if pages != nil && pages.pages != nil {
		t.Fatal("failed compressed open retained pages")
	}
}

// Keep the initial magic/header and later compressed prefix reads on the
// same bounded physical pages. The reader owns this descriptor on all paths.
physicalFile := newHistoryPhysicalPages(ctx, file, uint64(stat.Size()), historyDirectoryPageSize)

